const item = $input.first().json;
const raw = item.choices ? item.choices[0].message.content : null;

if (!raw) return [{ json: item }];

const cleanText = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const data = JSON.parse(cleanText);

// Récupérer nom + prenom depuis le webhook (source de vérité)
const nomRaw = $('Webhook1').first().json.body.name || '';
const prenomRaw = $('Webhook1').first().json.body.firstName || '';

function normaliser(str) {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}
// Expériences
const experiencesBlock = (data.experiences || []).map(exp => {
  let descriptionText = '';

  if (Array.isArray(exp.description)) {
    descriptionText = exp.description.join('\n');
  } else if (typeof exp.description === 'string') {
    descriptionText = exp.description;
  } else if (typeof exp.description === 'object' && exp.description !== null) {
    descriptionText = Object.values(exp.description).join('\n');
  }

  const missions = (descriptionText || '')
    .split('\n')
    .filter(line => line.trim() !== '')
    .map(line => '• ' + line.trim().replace(/^[•\-\*]+\s*/, ''))
    .join('\n');

  return `${exp.poste || ''}
${exp.entreprise || ''} — ${exp.periode || ''}


${missions}`;
}).join('\n\n\n');

// Formations (même ligne pour période)
const educationBlock = (data.formations || []).map(f => {
  return `${f.diplome || ''}
${f.etablissement || ''} — ${f.periode || ''}`;
}).join('\n\n');

// Compétences
const competencesBlock = (data.competences || []).map(c => {
  if (typeof c === 'string') return '• ' + c;
  const outils = Array.isArray(c.outils) ? c.outils.join(', ') : (c.outils || '');
  return '• ' + (c.categorie || '') + ' : ' + outils;
}).join('\n');

// Langues
const languesBlock = (data.langues || []).map(l => {
  if (typeof l === 'string') return '• ' + l;
  return '• ' + (l.langue || '') + ' : ' + (l.niveau || '');
}).join('\n');

// Certifications
const certificationsBlock = (data.certifications || []).map(c => {
  if (typeof c === 'string') return '• ' + c;
  return '• ' + (c.nom || '') + ' — ' + (c.organisme || '') + ' — ' + (c.annee || '');
}).join('\n');

return [{
  json: {
    nom_prenom: `${prenomRaw} ${nomRaw}`.trim(),
    email: data.email || '',
    telephone: data.telephone || '',
    linkedin: data.linkedin || '',
    github_username: data.github_username || '',
    profil: data.profil || '',
    experiences: experiencesBlock,
    formations: educationBlock,
    certifications: certificationsBlock,
    competences: competencesBlock,
    langues: languesBlock,
    filename: `${normaliser(nomRaw)}_${normaliser(prenomRaw)}_unifie`
  }
}];

const item = $input.first().json;

// Si déjà parsé (vient de la branche DOCX)
if (item.nom_prenom !== undefined) return [{ json: item }];

// Sinon parser la réponse Gemini (PDF/Image)
const rawText = item.choices ? item.choices[0].message.content : null;

const cleanText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const data = JSON.parse(cleanText);
// Récupérer nom + prenom depuis le webhook (source de vérité)
const nomRaw = $('Webhook1').first().json.body.name || '';
const prenomRaw = $('Webhook1').first().json.body.firstName || '';

function normaliser(str) {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/[^a-z0-9_]/g, '');
}

// Expériences (robuste)
const experiencesBlock = (data.experiences || []).map(exp => {
  let descriptionText = '';

  if (Array.isArray(exp.description)) {
    descriptionText = exp.description.join('\n');
  } else if (typeof exp.description === 'string') {
    descriptionText = exp.description;
  } else if (typeof exp.description === 'object' && exp.description !== null) {
    descriptionText = Object.values(exp.description).join('\n');
  }

  const missions = (descriptionText || '')
    .split('\n')
    .filter(line => line.trim() !== '')
    .map(line => `• ${line.trim().replace(/^[•\-\*]+\s*/, '')}`)
    .join('\n');

  return `${exp.poste || ''}
${exp.entreprise || ''} — ${exp.periode || ''}


${missions}`;
}).join('\n_____________________\n\n\n');

// Formations
const educationBlock = (data.formations || []).map(f => {
  return `${f.diplome || ''}
${f.etablissement || ''} — ${f.periode || ''}`;
}).join('\n\n');


// Compétences
const competencesBlock = (data.competences || []).map(c => {
  if (typeof c === 'string') return `• ${c}`;
  const outils = Array.isArray(c.outils) 
    ? c.outils.join(', ') 
    : (c.outils || '');
  return `• ${c.categorie || ''} : ${outils}`;
}).join('\n');

// Langues
const languesBlock = (data.langues || []).map(l => {
  if (typeof l === 'string') return `• ${l}`;
  return `• ${l.langue || ''} : ${l.niveau || ''}`;
}).join('\n');

// Certifications
const certificationsBlock = (data.certifications || []).map(c => {
  if (typeof c === 'string') return `• ${c}`;
  return `• ${c.nom || ''} — ${c.organisme || ''} — ${c.annee || ''}`;
}).join('\n');

return [{
  json: {
    nom_prenom: `${prenomRaw} ${nomRaw}`.trim(),
    email: data.email || '',
    telephone: data.telephone || '',
    linkedin: data.linkedin || '',
    github_username: data.github_username || '',
    profil: data.profil || '',
    experiences: experiencesBlock,
    formations: educationBlock,
    certifications: certificationsBlock,
    competences: competencesBlock,
    langues: languesBlock,
    filename: `${normaliser(nomRaw)}_${normaliser(prenomRaw)}_unifie`
  }
}];

const upload = $('Upload PDF vers CVs_Unifiés1').first().json;
const parsedData = $('Parser & Formater JSON1').first().json;
return [{
  json: {
    success: true,
    document_id: $('Upload PDF vers CVs_Unifiés1').first().json.id,
    document_name: $('Upload PDF vers CVs_Unifiés1').first().json.name || "CV_Unifié.pdf",
    document_url: $('Upload PDF vers CVs_Unifiés1').first().json.webViewLink,
    download_url: `https://drive.google.com/uc?id=${$('Upload PDF vers CVs_Unifiés1').first().json.id}&export=download` ,
  email: parsedData.email || null,
  github_username: parsedData.github_username || null,
  }
}];

const text = $input.first().json.text;

if (!text || text.trim() === '') {
  throw new Error('Aucun texte extrait du PDF.');
}

return [{
  json: {
    body: JSON.stringify({
      model: 'openrouter/free',
      messages: [
        {
          role: 'user',
          content: `Extrait les informations de ce CV et retourne UNIQUEMENT un JSON valide, sans markdown, sans explication :
{
  "nom_prenom": "",
  "email": "",
  "telephone": "",
  "linkedin": "",
  "github_username": "",
  "profil": "",
  "experiences": [{"poste":"","entreprise":"","periode":"","description":""}],
  "certifications": [{"nom":"","organisme":"","annee":""}],
  "competences": [{"categorie":"","outils":[""]}],
  "langues": [{"langue":"","niveau":""}],
  "formations": [{"diplome":"","etablissement":"","periode":""}]
}

CV : ${text}`
        }
      ]
    })
  }
}];

const convertApiSecret = process.env.CONVERTAPI_SECRET;
const openRouterApiKey = process.env.OPENROUTER_API_KEY;

if (!convertApiSecret) {
  throw new Error('Missing CONVERTAPI_SECRET in n8n environment');
}

if (!openRouterApiKey) {
  throw new Error('Missing OPENROUTER_API_KEY in n8n environment');
}

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'cv_binary');
const base64Data = binaryBuffer.toString('base64');
const fileName = $input.first().binary.cv_binary.fileName || 'cv.docx';

// Étape 1 : Convertir DOCX en TXT via ConvertAPI
const convertResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://v2.convertapi.com/convert/docx/to/txt?Secret=${convertApiSecret}`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    Parameters: [{
      Name: 'File',
      FileValue: { Name: fileName, Data: base64Data }
    }]
  })
});

// Étape 2 : Décoder le texte (ConvertAPI retourne FileData en base64)
const fileData = convertResponse.Files[0].FileData;
const text = Buffer.from(fileData, 'base64').toString('utf-8');

if (!text || text.trim().length < 50) {
  throw new Error('Texte extrait trop court : ' + text);
}

// Étape 3 : Envoyer le texte à OpenRouter
const openRouterResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://openrouter.ai/api/v1/chat/completions',
  headers: {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${openRouterApiKey}`
  },
  body: JSON.stringify({
    model: 'openrouter/free',
    messages: [{
      role: 'user',
      content: `Extrait les informations de ce CV et retourne UNIQUEMENT un JSON valide, sans markdown, sans explication :
{
  "nom_prenom": "",
  "email": "",
  "telephone": "",
  "linkedin": "",
  "github_username": "",
  "profil": "",
  "experiences": [{"poste":"","entreprise":"","periode":"","description":""}],
  "certifications": [{"nom":"","organisme":"","annee":""}],
  "competences": [{"categorie":"","outils":[""]}],
  "langues": [{"langue":"","niveau":""}],
  "formations": [{"diplome":"","etablissement":"","periode":""}]
}

CV :
${text}`
    }]
  })
});

return [{ json: openRouterResponse }];
